g5.submitCalculation = function () {
    const quantity = ee.getControl("quantity2")._input;
    const price = ee.getControl("unitprice")._input;
    if (!quantity.reportValidity() || !price.reportValidity()) return;
    ee.setText(ee.getControl("taskTotalResult"), "Waiting for eServer...");
    calculateTotal();
};
for (const input of [ee.getControl("quantity2")._input, ee.getControl("unitprice")._input]) {
    input.addEventListener("keydown", event => { if (event.key === "Enter") g5.submitCalculation(); });
}

const input = sender._input;
input.setAttribute("type", "number");
input.setAttribute("name", "quantity");
input.setAttribute("min", "1");
input.setAttribute("max", "99");
input.setAttribute("value", "3");
input.setAttribute("required", "true");
input.setAttribute("aria-label", "Quantity");

const input = sender._input;
input.setAttribute("type", "number");
input.setAttribute("name", "unitPrice");
input.setAttribute("min", "1");
input.setAttribute("max", "10000");
input.setAttribute("value", "250");
input.setAttribute("required", "true");
input.setAttribute("aria-label", "Unit price in cents");

sender.setAttribute("role", "button");
sender.setAttribute("tabindex", "0");
sender.addEventListener("keydown", event => {
    if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        sender.eeOnClick(sender, event);
    }
});

