control.text:
const form = document.getElementById("task-total-form");
eio.appendInt32(Number(form.elements.quantity.value));
eio.appendInt32(Number(form.elements.unitPrice.value));

var quantity = eio.readInt32();
var unitPrice = eio.readInt32();
var valid = quantity >= 1 && quantity <= 99
    && unitPrice >= 1 && unitPrice <= 10000;
eio.appendInt32(valid ? quantity * unitPrice : 0);

const total = eio.readInt32();
const result = document.getElementById("task-total-result");
result.textContent = total > 0
    ? "eServer total: " + total + " cents."
    : "eServer rejected the quantity or unit price.";

