control.text:
CREATE TABLE dbo.DemoTasks (
    TaskId INT PRIMARY KEY,
    Title NVARCHAR(100) NOT NULL,
    Status INT NOT NULL CHECK (Status IN (0, 1))
);
INSERT INTO dbo.DemoTasks (TaskId, Title, Status)
VALUES (1, N'Check page layout', 0);

var rows = db.executeQuery("DemoDb",
    "SELECT TaskId, Title, Status FROM dbo.DemoTasks ORDER BY TaskId");
if (rows == null) {
    eio.appendString8("F");
    es.logWarning("DemoTasks query failed");
    return;
}
eio.appendString8("T");
eio.appendDataSet(rows, "TaskId,Title,Status", 0, 20);

var status = eio.readString8();
if (status === "T") {
    var rows = eio.readDataSet();
    ee.setTableData(ee.getControl("taskTable"), rows, 0);
} else {
    ee.setText(ee.getControl("taskMessage"), "Could not load tasks.");
}

var taskId = eio.readInt32();
var status = eio.readInt32();
if (taskId < 1 || (status !== 0 && status !== 1)) {
    eio.appendString8("F");
    return;
}

var sql = "UPDATE dbo.DemoTasks SET Status = " + status
    + " WHERE TaskId = " + taskId;
var ok = db.executeNoneQuery("DemoDb", sql);
eio.appendString8(ok ? "T" : "F");

var ok = eio.readString8() === "T";
ee.setText(ee.getControl("taskMessage"),
    ok ? "Update submitted." : "Could not update the task.");
if (ok) loadDemoTasks();

var ok = db.executeNoneQuery("DemoDb",
    "INSERT INTO dbo.DemoTasks (TaskId, Title, Status) "
    + "VALUES (2, N'Review task list', 0)");
eio.appendString8(ok ? "T" : "F");

var ok = db.executeNoneQuery("DemoDb",
    "DELETE FROM dbo.DemoTasks WHERE TaskId = 2");
eio.appendString8(ok ? "T" : "F");

